                                                'def line(\n',
                                                '    s: Length64, x: Length64, y: Length64, heading: '
                                                'Angle64, length: Length64\n',
                                                ') raises -> RoadGeometry:\n',
                                                '    """Create a checked Float64 line record.\n',
                                                '\n',
                                                '    Args:\n',
                                                '        s: Its start station.\n',
                                                '        x: Its east coordinate.\n',
                                                '        y: Its north coordinate.\n',
                                                '        heading: Its heading.\n',
                                                '        length: Its positive length.\n',
                                                '\n',
                                                '    Returns:\n',
                                                '        A line with unchanged Float64 inputs.\n',
                                                '\n',
                                                '    Raises:\n',
                                                '        Error: If any value is not finite or its domain is '
                                                'invalid.\n',
                                                '    """\n',
                                                '    return RoadGeometry(LINE, s, x, y, heading, length)\n',
                                                '\n',
                                                '\n',
                                                'def with_arc(\n',
                                                '    var base: RoadGeometry, curvature: InverseLength64\n',
                                                ') raises -> RoadGeometry:\n',
                                                '    """Set the typed Float64 curvature of an arc.\n',
                                                '\n',
                                                '    Args:\n',
                                                '        base: The source record.\n',
                                                '        curvature: Its finite nonzero curvature.\n',
                                                '\n',
                                                '    Returns:\n',
                                                '        The arc record.\n',
                                                '\n',
                                                '    Raises:\n',
                                                '        Error: If curvature is not finite or is zero.\n',
                                                '    """\n',
                                                '    return with_arc_si(base^, curvature.value)\n',
                                                '\n',
                                                '\n',
