                                                'struct NormalizedCubic(ImplicitlyCopyable):\n',
                                                '    """A length-valued cubic of a dimensionless normalized '
                                                'parameter.\n',
                                                '\n',
                                                '    Every coefficient is a length. This is deliberately a '
                                                'different type\n',
                                                '    from a road-station CubicPolynomial; raw CARLA storage '
                                                'is shared only\n',
                                                '    after the parameter mode has been selected '
                                                'explicitly.\n',
                                                '    """\n',
                                                '\n',
                                                '    var a: Length64\n',
                                                '    var b: Length64\n',
                                                '    var c: Length64\n',
                                                '    var d: Length64\n',
                                                '\n',
                                                '    def __init__(\n',
                                                '        out self, a: Length64, b: Length64, c: Length64, d: '
                                                'Length64\n',
                                                '    ) raises:\n',
                                                '        """Create finite coefficients for a normalized '
                                                'parameter.\n',
                                                '\n',
                                                '        Args:\n',
                                                '            a: The constant length coefficient.\n',
                                                '            b: The linear length coefficient.\n',
                                                '            c: The quadratic length coefficient.\n',
                                                '            d: The cubic length coefficient.\n',
                                                '\n',
                                                '        Returns:\n',
                                                '            The initialized NormalizedCubic record.\n',
                                                '\n',
                                                '        Raises:\n',
                                                '            Error: If any coefficient is not finite.\n',
                                                '        """\n',
                                                '        self.a = Length64(_finite_si(a.value))\n',
                                                '        self.b = Length64(_finite_si(b.value))\n',
                                                '        self.c = Length64(_finite_si(c.value))\n',
                                                '        self.d = Length64(_finite_si(d.value))\n',
                                                '\n',
                                                '    @staticmethod\n',
                                                '    def from_meters(\n',
                                                '        a: Float64, b: Float64, c: Float64, d: Float64\n',
                                                '    ) raises -> NormalizedCubic:\n',
                                                '        """Read four explicit meter-valued normalized '
                                                'source coefficients.\n',
                                                '\n',
                                                '        Args:\n',
                                                '            a: The constant coefficient in meters.\n',
                                                '            b: The linear coefficient in meters.\n',
                                                '            c: The quadratic coefficient in meters.\n',
                                                '            d: The cubic coefficient in meters.\n',
                                                '\n',
                                                '        Returns:\n',
                                                '            The checked normalized polynomial without '
                                                'narrowing.\n',
                                                '\n',
                                                '        Raises:\n',
                                                '            Error: If any coefficient is not finite.\n',
                                                '        """\n',
                                                '        return NormalizedCubic(\n',
                                                '            Length64(a), Length64(b), Length64(c), '
                                                'Length64(d)\n',
                                                '        )\n',
                                                '\n',
                                                '    def _coefficients(self) raises -> CubicPolynomial:\n',
                                                '        return CubicPolynomial.from_coefficients(\n',
                                                '            self.a.value, self.b.value, self.c.value, '
                                                'self.d.value, 0\n',
                                                '        )\n',
                                                '\n',
                                                '    def evaluate(self, p: Float64) raises -> Length64:\n',
                                                '        """Evaluate at a finite dimensionless normalized '
                                                'coordinate.\n',
                                                '\n',
                                                '        Args:\n',
                                                '            p: The parameter, between zero and one '
                                                'inclusive.\n',
                                                '\n',
                                                '        Returns:\n',
                                                '            The physical value in Float64 precision.\n',
                                                '\n',
                                                '        Raises:\n',
                                                '            Error: If a coefficient, parameter or result is '
                                                'invalid.\n',
                                                '        """\n',
                                                '        _ = _finite_si(p)\n',
                                                '        if p < 0 or p > 1:\n',
                                                '            raise Error(\n',
                                                '                "A normalized polynomial parameter must be '
                                                'from zero"\n',
                                                '                " through one"\n',
                                                '            )\n',
                                                '        var polynomial = self._coefficients()\n',
                                                '        return '
                                                'Length64(_finite_si(polynomial._evaluate_si(p)))\n',
                                                '\n',
                                                '    def tangent(self, p: Float64) raises -> Length64:\n',
                                                '        """Differentiate with respect to the dimensionless '
                                                'parameter.\n',
                                                '\n',
                                                '        Args:\n',
                                                '            p: The parameter, between zero and one '
                                                'inclusive.\n',
                                                '\n',
                                                '        Returns:\n',
                                                '            The length-valued derivative, not a '
                                                'dimensionless station slope.\n',
                                                '\n',
                                                '        Raises:\n',
                                                '            Error: If a coefficient, parameter or result is '
                                                'invalid.\n',
                                                '        """\n',
                                                '        _ = _finite_si(p)\n',
                                                '        if p < 0 or p > 1:\n',
                                                '            raise Error(\n',
                                                '                "A normalized polynomial parameter must be '
                                                'from zero"\n',
                                                '                " through one"\n',
                                                '            )\n',
                                                '        var polynomial = self._coefficients()\n',
                                                '        return '
                                                'Length64(_finite_si(polynomial._tangent_si(p)))\n',
                                                '\n',
                                                '\n',
                                                'def with_param_poly3(\n',
                                                '    var base: RoadGeometry,\n',
                                                '    u: CubicPolynomial,\n',
                                                '    v: CubicPolynomial,\n',
                                                '    max_samples: Int = 4194304,\n',
                                                ') raises -> RoadGeometry:\n',
