EDGES_SHA256 = 'df6f624e80c263102b9d717cb8f83bec06bae26e11e4c36276a135935106e45d'
# END REVIEWED TYPED BOUNDARY DATA


def require(value, message):
    if not value:
        raise ValueError('reviewed typed boundary successor: ' + message)


def sha(text):
    require(type(text) in (str, bytes), 'source is not immutable text or bytes')
    return hashlib.sha256(text.encode('utf-8') if type(text) is str else text).hexdigest()


def is_current(path, text):
    return path in EDGES and sha(text) == EDGES[path]['after_sha256']



_LEXICAL_HELPER = source.token_sha256


def _frozen_defaults(value):
    """Copy only primitive defaults; never retain a mutable defaults mapping."""
    if value is None or type(value) in (bool, int, float, str, bytes):
        return (type(value).__name__, value)
    if type(value) is tuple:
        return ('tuple', tuple(_frozen_defaults(item) for item in value))
    if type(value) is dict and all(type(key) is str for key in value):
        return ('dict', tuple((key, _frozen_defaults(value[key])) for key in sorted(value)))
    raise ValueError('nonprimitive lexical defaults')


def _lexical_domain():
    """Identify the parser domain without retaining any lexical result."""
    import functools
    import types
    try:
        if (type(_LEXICAL_HELPER) is not functools._lru_cache_wrapper or
                type(source._token_snapshot) is not functools._lru_cache_wrapper or
                type(source.tokens) is not types.FunctionType):
            return None
        functions = (_LEXICAL_HELPER, _LEXICAL_HELPER.__wrapped__,
            source.tokens, source._token_snapshot, source._token_snapshot.__wrapped__,
            source.tokenize.generate_tokens,
            source.tokenize._generate_tokens_from_c_tokenizer,
            source.tokenize._tokenize.TokenizerIter, source.tokenize.TokenInfo,
            source.tokenize.TokenInfo._make.__func__, source.io.StringIO,
            source.hashlib.sha256, source.json.dumps)
        return (tuple((value, getattr(value, '__code__', None),
                       _frozen_defaults(getattr(value, '__defaults__', None)),
                       _frozen_defaults(getattr(value, '__kwdefaults__', None)))
                      for value in functions),
                (source.tokenize.COMMENT, source.tokenize.NL, source.tokenize.ENDMARKER))
    except (AttributeError, TypeError, ValueError):
        return None


def _same_lexical_domain(current, captured):
    if current is None or captured is None or len(current[0]) != len(captured[0]):
        return False
    return (current[1] == captured[1] and all(
        actual[0] is expected[0] and actual[1] is expected[1]
        and actual[2:] == expected[2:]
        for actual, expected in zip(current[0], captured[0])))


# Captured parser identity only, never source text or a verifier result. The
# optimized exact-byte implication is used only in this pinned plain domain.
_LEXICAL_DOMAIN = _lexical_domain() if sys.version_info[:2] == (3, 12) else None


def predecessor_source(path, text):
    """Recover one exact typed predecessor, with no fuzzy or token-only match."""
    require(path in EDGES and type(text) is str, 'unknown typed source')
    edge = EDGES[path]
    require(sha(json.dumps(edge, sort_keys=True, separators=(',', ':'))) == EDGE_SHA256[path],
            'reviewed inverse changed: ' + path)
    require(sha(text) == edge['after_sha256'],
            'unknown complete typed endpoint: ' + path)
    lines = text.splitlines(keepends=True)
    # Coordinates refer to the exact current endpoint. Reverse order preserves
    # all earlier coordinates. Empty insertions/deletions remain explicit.
    previous = len(lines) + 1
    for edit in reversed(edge['edits']):
        start, stop, before, after = edit
        require(type(start) is int and type(stop) is int and
                0 <= start <= stop < previous and
                all(type(line) is str for line in (*before, *after)),
                'unordered or malformed inverse: ' + path)
        require(lines[start:stop] == after, 'inverse span changed: ' + path)
        lines[start:stop] = before
        previous = start
    before = ''.join(lines)
    require(sha(before) == edge['before_sha256'],
            'inverse did not recover exact predecessor: ' + path)
    # Complete byte identities already determine lexical identity. Complete
    # admission checks both token digests; provenance need not tokenize again.
    # A replacement public helper is still invoked directly, preserving its
    # effects and refusals. A changed parser cannot reuse a prior LRU entry:
    # reject that domain even when such an entry returns the expected digest.
    if _LEXICAL_DOMAIN is None or source.token_sha256 is not _LEXICAL_HELPER:
        require(source.token_sha256(text) == edge['after_token_sha256'] and
                source.token_sha256(before) == edge['before_token_sha256'],
                'changed lexical evaluator rejected exact predecessor: ' + path)
    if _LEXICAL_DOMAIN is not None:
        require(_same_lexical_domain(_lexical_domain(), _LEXICAL_DOMAIN),
                'lexical parser domain changed: ' + path)
    return before


def historical_source(path, text):
    """Project a known current endpoint for historical comparisons only."""
    if not is_current(path, text):
        return text
    prior = predecessor_source(path, text)
    if path in conditioned.SOURCE_PATHS:
        require(sha(prior) == conditioned.AFTER_SHA256[path],
                'typed edge misses conditioned endpoint: ' + path)
        return conditioned.predecessor_source(path, prior)
    return prior


def verify_sources(texts):
    """Require the complete current typed graph before semantic composition."""
    verify_authority()
    require(type(texts) is dict and set(texts) == set(SOURCE_PATHS),
            'missing or extra typed source')
    require(sha(json.dumps(EDGES, sort_keys=True, separators=(',', ':'))) == EDGES_SHA256,
            'reviewed inverse inventory changed')
    predecessors = {path: predecessor_source(path, texts[path]) for path in SOURCE_PATHS}
    for path, prior in predecessors.items():
        require(source.token_sha256(texts[path]) == EDGES[path]['after_token_sha256'] and
                source.token_sha256(prior) == EDGES[path]['before_token_sha256'],
                'complete admission lexical endpoint changed: ' + path)
    conditioned.verify_sources({path: predecessors[path] for path in conditioned.SOURCE_PATHS})
    # These are the exact predecessors just reconstructed in this call.
    # Compose the semantic edge without reconstructing every typed edge twice.
    return {path: (conditioned.predecessor_source(path, prior)
                   if path in conditioned.SOURCE_PATHS else prior)
            for path, prior in predecessors.items()}


def edge(path):
    """Describe a provenance edge; physical admission is a separate check."""
    require(path in EDGES, 'unknown typed edge')
    result = {key: EDGES[path][key] for key in
              ('before_sha256', 'after_sha256', 'before_token_sha256', 'after_token_sha256')}
    if path in conditioned.SOURCE_PATHS:
        require(result['before_sha256'] == conditioned.AFTER_SHA256[path] and
                result['before_token_sha256'] == conditioned.AFTER_TOKEN_SHA256[path],
                'conditioned edge join changed: ' + path)
        result['before_sha256'] = conditioned.BEFORE_SHA256[path]
        result['before_token_sha256'] = conditioned.BEFORE_TOKEN_SHA256[path]
    return {'path': path, **result}


def verify_authority():
    """Refuse changed authoritative globals, including late namespace edits."""
    payload = {
        'SOURCE_PATHS': SOURCE_PATHS, 'EDGES': EDGES, 'EDGE_SHA256': EDGE_SHA256,
        'NEW_INPUTS': NEW_INPUTS, 'TESTS': TESTS, 'BINDING_INPUTS': BINDING_INPUTS,
        'PRODUCTION_CLOSURE': PRODUCTION_CLOSURE, 'NATIVE_CLOSURE': NATIVE_CLOSURE,
        'TYPED_NATIVE_CLOSURE': TYPED_NATIVE_CLOSURE,
        'TYPED_PRODUCTION_CLOSURE': TYPED_PRODUCTION_CLOSURE,
        'CURRENT_DEPENDENCIES': CURRENT_DEPENDENCIES, 'INVENTORY': INVENTORY,
        'EDGES_SHA256': EDGES_SHA256,
    }
    require(sha(json.dumps(payload, sort_keys=True, separators=(',', ':'))) ==
            'e4427b5cacd7ac15dc943330e554dda581693c99fabb644b791450b504b5c2e4', 'executing authority globals changed')
